"""Independent explanations following the mathematical sequence of book 24.1–24.4."""
import re
import sympy as s
lessons=[];models=[]
def T(value):return s.latex(s.sympify(value))
def D(*rows):return r'\[\begin{gathered}'+r'\\'.join(rows)+r'\end{gathered}\]'
def E(code,title,question,worked,kind,**data):
 uid='FODE-E-'+code;models.append(dict(id=uid,kind=kind,**data));return dict(title=title,question=question,solution=worked,verification=uid)
def markup(value):
 """Typeset our prose formulas without changing existing TeX, HTML or owner content."""
 replacements={
  'y′+P(x)y=Q(x)':r'y^{\prime}+P(x)y=Q(x)',
  'ay′′+by′+cy=0':r'ay^{\prime\prime}+by^{\prime}+cy=0',
  'p=Ux²+Vx+W':r'p=Ux^2+Vx+W','Ux²+Vx+W':r'Ux^2+Vx+W',
  'sqrt(U²+V²)':r'\sqrt{U^2+V^2}',
  'U sin(ωx)+V cos(ωx)':r'U\sin(\omega x)+V\cos(\omega x)',
  'R sin(ωx+φ)':r'R\sin(\omega x+\phi)',
  'R cos φ=U':r'R\cos\phi=U','R sin φ=V':r'R\sin\phi=V',
  'v′(x₀)=g′(x₀)y(x₀)+g(x₀)y′(x₀)':r'v^{\prime}(x_0)=g^{\prime}(x_0)y(x_0)+g(x_0)y^{\prime}(x_0)',
  'v=φ(y)':r'v=\phi(y)','v=g(x)y':r'v=g(x)y',
  'y=xv':r'y=xv','y′=v+xv′':r'y^{\prime}=v+xv^{\prime}',
  'z=ax+by':r'z=ax+by','z′=a+by′':r'z^{\prime}=a+by^{\prime}',
  'x=eᵘ':r'x=e^u','u=ln x':r'u=\ln x','v=1/y':r'v=\frac1y',
  'e⁻ˣcos x':r'e^{-x}\cos x','eˣcos x':r'e^x\cos x',
  'Kx²e⁻²ˣ':r'Kx^2e^{-2x}','Kxeˣ':r'Kxe^x','3Keˣ':r'3Ke^x',
  'L(Pe⁻²ˣ)=P′′e⁻²ˣ':r'L(Pe^{-2x})=P^{\prime\prime}e^{-2x}',
  'P′′':r'P^{\prime\prime}','e⁻²ˣ':r'e^{-2x}','e²ˣ':r'e^{2x}',
  'e⁻ˣ':r'e^{-x}','eᵃˣ':r'e^{ax}','eʳˣ':r'e^{rx}','Feᵏˣ':r'Fe^{kx}',
  'yᵤᵤ+2yᵤ+5y':r'y_{uu}+2y_u+5y','xyₓ=yᵤ':r'xy_x=y_u',
  'yᵤ=xyₓ=yₓ':r'y_u=xy_x=y_x','−a±bi':r'-a\pm bi',
  '−aA+bB=v₀':r'-aA+bB=v_0','A=y₀':r'A=y_0',
  'A+B=y₀':r'A+B=y_0','r₁A+r₂B=v₀':r'r_1A+r_2B=v_0',
  'P=A+Bx':r'P=A+Bx','y′(0)=B−kA':r'y^{\prime}(0)=B-kA',
  'v′−av=−b':r'v^{\prime}-av=-b','v=b/a+Ceᵃˣ':r'v=\frac ba+Ce^{ax}',
  'rate−kL=0':r'\mathrm{rate}-kL=0','C=y(0)−L':r'C=y(0)-L',
  'x−1/2':r'x-\frac12','S/20':r'\frac S{20}','sin3x':r'\sin3x',
  'v=y²':r'v=y^2','v=y⁴':r'v=y^4','p=x²−1':r'p=x^2-1'
 }
 def part(text):
  for plain,tex in sorted(replacements.items(),key=lambda pair:-len(pair[0])):
   text=text.replace(plain,r'\('+tex+r'\)')
  # Conditions and short parameter values are mathematical expressions too.
  text=re.sub(r'(?<![A-Za-z\\])y(′)?\((\d+)\)=([−-]?\d+(?:/\d+)?)',lambda m:r'\(y'+(r'^{\prime}' if m[1] else '')+'('+m[2]+')='+T(s.Rational(m[3].replace('−','-')))+r'\)',text)
  return text
 return ''.join(chunk if re.match(r'^<|^\\[\[(]',chunk) else part(chunk) for chunk in re.split(r'(<[^>]+>|\\\[.*?\\\]|\\\(.*?\\\))',value,flags=re.S))
def L(key,title,summary,objective,before,ideas,method,mistakes,examples):
 for example in examples:
  example['question']=markup(example['question']);example['solution']=markup(example['solution'])
 lessons.append(dict(key=key,id='fp2_ode_'+key,title=title,summary=summary,objective=objective,before=before,ideas=markup(ideas),method='<ol>'+''.join('<li>'+markup(z)+'</li>' for z in method)+'</ol>',mistakes=[markup(z) for z in mistakes],examples=examples))
base='/courses/maths4u-9231-fp2/topics/fp2_ode_'
def before(key):return '<p>Complete <a href="'+base+key+'">the preceding lesson</a>. Work on the stated real interval and retain exact values.</p>'
L('first','Linear first-order equations and models','Turn the left-hand side into one product derivative.',
 'Use an integrating factor, apply the initial condition and identify the solution interval.',
 '<p>Review the product and chain rules, separable equations and <a href="/courses/maths4u-9231-fp2/topics/fp2_integration_techniques">integration techniques</a>. Logarithmic, trigonometric and hyperbolic factors may require earlier Pure Mathematics identities.</p>',
 r'''<h3>Divide into standard form first</h3><p>A linear first-order equation can be written as y′+P(x)y=Q(x) on an interval where its leading coefficient is non-zero. The coefficient of y′ must be 1 before identifying P. A non-zero integrating factor converts the left side into a product derivative.</p>'''+D(r'\mu=e^{\int P(x)\,dx},\qquad\frac{\mu^{\prime}}\mu=P',r'(\mu y)^{\prime}=\mu Q',r'y=\frac{\int\mu Q\,dx+C}{\mu}')+r'''<p>One multiplicative constant in μ is unnecessary; it is absorbed into C. Integrate first, then apply the initial condition to the whole solution. A constant must not be placed in a different part of the expression when dividing by μ.</p><h3>The interval belongs to the original equation</h3><p>Record forbidden points from the original leading coefficient and denominators. A cancelled factor does not restore a point where the original equation is undefined. Use a connected interval containing the initial point. For logarithms, use absolute values when required; remove them only after fixing a branch on that interval.</p><h3>Exceptional parameter values</h3><p>A general parameter formula may divide by zero at a special value. Solve the equation at that value directly instead of discarding the case. An exponential forcing with the same rate as the homogeneous solution can produce a factor x.</p><h3>Build a model from rates</h3><p>For a well-mixed tank, mass change equals mass entering per unit time minus mass leaving per unit time. The outgoing concentration is current mass divided by current volume. State constant-volume and mixing assumptions. Distinguish mass, concentration and time units.</p><h3>A periodic approximation is not a limit</h3><p>A decaying transient may leave a non-constant oscillation. The difference from that oscillation tends to zero, while the function itself has no finite pointwise limit.</p>''',
 ['Specify the real interval and divide by the leading coefficient.','Identify P and construct a non-zero integrating factor.','Integrate the product derivative and keep one arbitrary constant.','Apply the initial condition and recover the original dependent variable.','Check the equation, interval, model units and any exceptional parameter value.'],
 ['Divide the whole equation, not only the y′ term.','The integrating factor uses P after standardisation.','Keep C inside the numerator when dividing by μ.','Cancelling a factor does not repair a singularity of the original equation.','A periodic long-term response is not a constant limit.'],[
 E('F1','1 · A polynomial input',r'<p>Solve \(y^{\prime}+3y=6x-1\), with y(0)=2.</p>',D(r'\mu=e^{3x},\qquad(e^{3x}y)^{\prime}=(6x-1)e^{3x}',r'e^{3x}y=(2x-1)e^{3x}+C',r'C=3,\qquad y=2x-1+3e^{-3x}')+'<p>The final exponential term satisfies the homogeneous equation; differentiating the whole result verifies both the input and the initial value.</p>','linear',a='1',b='3',c='0',forcing='6*x-1',solution='2*x-1+3*exp(-3*x)',initial=[['0','2']]),
 E('F2','2 · Keep the original interval',r'<p>For x&gt;0, solve \(y^{\prime}+\frac2x y=x^2\), with y(1)=2.</p>',D(r'\mu=x^2,\qquad(x^2y)^{\prime}=x^4',r'x^2y=\frac{x^5}{5}+C,\qquad C=\frac95',r'y=\frac{x^3}{5}+\frac9{5x^2}')+'<p>The equation is undefined at zero. The solution to this initial-value problem is considered on x&gt;0, even though the algebraic formula can also be evaluated on a separate negative interval.</p>','linear',a='1',b='2/x',c='0',forcing='x**2',solution='x**3/5+9/(5*x**2)',initial=[['1','2']]),
 E('F3','3 · Solve the exceptional case separately',r'<p>Solve \(y^{\prime}+ky=3e^{-x}\), y(0)=2, distinguishing k=1.</p>',D(r'k\ne1:\quad y=\frac3{k-1}e^{-x}',r'\quad+\left(2-\frac3{k-1}\right)e^{-kx}',r'k=1:\quad(e^xy)^{\prime}=3',r'y=(2+3x)e^{-x}')+'<p>The second formula is obtained from the original equation at k=1. For k&gt;0 both cases tend to zero, including the polynomial-times-exponential term.</p>','parameter_first',forcing=3,initial=2),
 E('F4','4 · Mass and concentration are different quantities',r'<p>A well-mixed tank holds 20 litres. It initially contains 10 grams of salt. Liquid containing 2 grams per litre enters at 1 litre per minute and leaves at the same rate. Find the concentration and when it first reaches 1.5 grams per litre.</p>',D(r'S^{\prime}=2-\frac S{20},\qquad S(0)=10',r'S=40-30e^{-t/20}',r'c=\frac S{20}=2-\frac32e^{-t/20}',r'c=\frac32\quad\Longrightarrow\quad t=20\ln3')+'<p>The outgoing mass rate is S/20 grams per minute. The concentration increases from 0.5 towards 2, so the stated crossing is unique.</p>','tank',volume=20,flow=1,concentration=2,mass0=10,solution='40-30*exp(-x/20)',target='3/2',time='20*log(3)')])
L('complementary','Complementary functions and initial conditions','Choose the correct two-constant form for the auxiliary roots.',
 'Construct second-order solutions and apply both conditions to the complete function.',before('first')+'<p>Review <a href="/courses/maths4u-9231-fp2/topics/fp2_complex_powers">complex powers</a> for the real form arising from conjugate auxiliary roots.</p>',
 r'''<h3>Start with the homogeneous equation</h3><p>For constant coefficients, try an exponential in ay′′+by′+cy=0. Its non-zero factor leaves the auxiliary equation. The leading coefficient a must be non-zero.</p>'''+D(r'a\lambda^2+b\lambda+c=0',r'\lambda_1\ne\lambda_2\text{ real}:\quad y_{\rm CF}=Ae^{\lambda_1x}+Be^{\lambda_2x}',r'\lambda\text{ repeated}:\quad y_{\rm CF}=(A+Bx)e^{\lambda x}',r'\alpha\pm i\beta:\quad y_{\rm CF}=e^{\alpha x}(A\cos\beta x+B\sin\beta x)')+r'''<p>For the conjugate-root form take β&gt;0. Two copies of the same exponential are not independent; that is why a repeated root needs the factor x. Each arbitrary constant belongs to the complementary function.</p><h3>Add a particular integral for the actual input</h3><p>If L(y) denotes ay′′+by′+cy and L(p)=f, then L(yCF+p)=f by linearity. A particular integral is one fixed function with no new arbitrary constants. It need not satisfy the initial conditions by itself.</p><h3>A first polynomial trial</h3><p>When the input is quadratic and c≠0, try p=Ux²+Vx+W. Substitution gives a triangular coefficient system.</p>'''+D(r'L(p)=cUx^2+(2bU+cV)x',r'\quad+(2aU+bV+cW)')+r'''<p>Match every coefficient with the given input, then add the complementary function. The next lesson develops these trials further.</p><h3>Use the conditions on the whole solution</h3><p>Differentiate the complete yCF+p before substituting. In a conjugate-root form the derivative includes the exponential factor as well as the trigonometric derivatives. Two independent conditions determine the two constants; check the resulting values in both conditions.</p><h3>Reading the homogeneous modes</h3><p>Negative real parts give decaying homogeneous terms. A zero real part can give persistent oscillation, and a positive real part allows growth. Repeated negative roots still decay despite the polynomial factor. Examine the actual constants before declaring that a growing mode is present.</p>''',
 ['Form the auxiliary equation and find its root type.','Write two independent homogeneous modes.','Find or verify a particular integral for a non-zero input.','Apply both conditions to the complete solution and its derivative.','Substitute back and interpret the actual modes.'],
 ['A repeated root needs x times the exponential as its second mode.','Use both real and imaginary parts of a conjugate-root pair correctly.','Differentiate the exponential factor as well as sine and cosine.','Initial conditions apply to CF plus PI, not CF alone.','A positive auxiliary root permits growth but its coefficient may vanish.'],[
 E('C1','1 · Two distinct real modes',r'<p>Solve \(y^{\prime\prime}+y^{\prime}-6y=0\), y(0)=3 and y′(0)=1.</p>',D(r'(\lambda-2)(\lambda+3)=0',r'y=Ae^{2x}+Be^{-3x}',r'A+B=3,\qquad2A-3B=1',r'A=2,\quad B=1,\qquad y=2e^{2x}+e^{-3x}')+'<p>The two rates are different, giving two independent modes. The positive-rate term is present for these particular conditions.</p>','second',a='1',b='1',c='-6',forcing='0',solution='2*exp(2*x)+exp(-3*x)',initial=[['0','3'],['0','1',1]]),
 E('C2','2 · A repeated auxiliary root',r'<p>Solve \(y^{\prime\prime}+4y^{\prime}+4y=0\), y(0)=1 and y′(0)=3.</p>',D(r'(\lambda+2)^2=0',r'y=(A+Bx)e^{-2x}',r'A=1,\qquad B-2A=3',r'y=(1+5x)e^{-2x}')+'<p>The solution decays as x increases, although its initial gradient is positive. Initial direction and long-term behaviour are different questions.</p>','second',a='1',b='4',c='4',forcing='0',solution='(1+5*x)*exp(-2*x)',initial=[['0','1'],['0','3',1]]),
 E('C3','3 · Real form from complex roots',r'<p>Solve \(y^{\prime\prime}+2y^{\prime}+10y=0\), y(0)=2 and y′(0)=1.</p>',D(r'\lambda=-1\pm3i',r'y=e^{-x}(A\cos3x+B\sin3x)',r'A=2,\qquad-A+3B=1',r'y=e^{-x}(2\cos3x+\sin3x)')+'<p>The coefficient of sin3x is 1, after the factor 3 in its derivative is included.</p>','second',a='1',b='2',c='10',forcing='0',solution='exp(-x)*(2*cos(3*x)+sin(3*x))',initial=[['0','2'],['0','1',1]]),
 E('C4','4 · The conditions apply to CF plus PI',r'<p>For \(y^{\prime\prime}+2y^{\prime}+5y=5x^2+4x-3\), verify p=x²−1 is a particular integral and find the solution with y(0)=y′(0)=0.</p>',D(r'L(x^2-1)=2+4x+5(x^2-1)',r'=5x^2+4x-3',r'y=x^2-1+e^{-x}(A\cos2x+B\sin2x)',r'A=1,\qquad-A+2B=0',r'y=x^2-1+e^{-x}\left(\cos2x+\frac12\sin2x\right)')+'<p>Using yCF(0)=0 instead would miss the −1 contributed by the particular integral.</p>','second',a='1',b='2',c='5',forcing='5*x**2+4*x-3',solution='x**2-1+exp(-x)*(cos(2*x)+sin(2*x)/2)',initial=[['0','0'],['0','0',1]])])
L('forcing','Polynomial and exponential particular integrals','Find the input response before fitting the homogeneous constants.',
 'Use suitable trials and superposition, then check the complete initial-value solution.',before('complementary'),
 r'''<h3>Keep CF and PI separate while working</h3><p>The complementary function solves the zero-input equation. A particular integral produces the specified right-hand side. If the equation is linear, the sum of particular integrals for separate inputs produces the sum of those inputs.</p><h3>Polynomial inputs need all lower powers</h3><p>For a quadratic input use Ux²+Vx+W when appropriate, including lower powers even if one is absent from the input. Differentiation mixes degrees. If the usual trial duplicates a homogeneous mode, a modified or supplied form is needed; the next lesson treats the stated resonant examples.</p><h3>Exponential inputs</h3>'''+D(r'L(Ke^{kx})=K(ak^2+bk+c)e^{kx}',r'K=\frac{F}{ak^2+bk+c}\quad\text{if the denominator is non-zero}')+r'''<p>This formula follows by differentiating the trial twice, not by replacing the derivatives with the input itself. The denominator being zero means the trial cannot produce a non-zero input; it does not mean that the differential equation has no solution.</p><h3>Superpose, then use the initial conditions</h3><p>For polynomial plus exponential forcing, add the two verified particular responses. Differentiate that entire expression before finding the complementary constants. A particular integral may be rewritten by adding a homogeneous term; what matters is the complete family and satisfaction of the original equation.</p><h3>Parameters can remove a mode</h3><p>When a free initial slope controls the coefficient of a growing exponential, solve for the slope that makes that coefficient zero. The remaining solution can still grow because of a polynomial input. Distinguish a finite limit, a polynomial approximation and a vanishing transient.</p>''',
 ['Find the complementary function once.','Choose a trial containing every required polynomial term or the correct exponential rate.','Differentiate and match coefficients with the input.','Combine inputs by addition, then apply the initial conditions to the whole function.','Check the residual and classify the surviving long-term terms.'],
 ['A quadratic trial usually needs constant and linear terms too.','A trial duplicating a CF mode cannot produce a non-zero input.','Superposition adds responses; it does not multiply them.','The PI generally does not satisfy the initial conditions alone.','Removing an unstable mode does not necessarily give a constant limit.'],[
 E('P1','1 · Match the whole quadratic',r'<p>Solve \(y^{\prime\prime}+3y^{\prime}+2y=2x^2+2x+2\), y(0)=1 and y′(0)=0.</p>',D(r'p=Ux^2+Vx+W',r'2U=2,\quad6U+2V=2,\quad2U+3V+2W=2',r'p=x^2-2x+3',r'y=Ae^{-x}+Be^{-2x}+p',r'A=-2,\quad B=0',r'y=x^2-2x+3-2e^{-x}')+'<p>Both constants are solved, even though one turns out to be zero.</p>','second',a='1',b='3',c='2',forcing='2*x**2+2*x+2',solution='x**2-2*x+3-2*exp(-x)',initial=[['0','1'],['0','0',1]]),
 E('P2','2 · A non-resonant exponential input',r'<p>Find the general solution of \(y^{\prime\prime}-y^{\prime}-2y=12e^{3x}\).</p>',D(r'\lambda=2,-1,\qquad p=Ke^{3x}',r'(9-3-2)K=12,\qquad K=3',r'y=Ae^{2x}+Be^{-x}+3e^{3x}')+'<p>The trial is independent of both complementary modes, so no extra polynomial factor is needed.</p>','second',a='1',b='-1',c='-2',forcing='12*exp(3*x)',solution='A*exp(2*x)+B*exp(-x)+3*exp(3*x)'),
 E('P3','3 · Add responses for two inputs',r'<p>Find the general solution of \(y^{\prime\prime}+3y^{\prime}+2y=2x+7+6e^x\).</p>',D(r'L(x+2)=2x+7,\qquad L(e^x)=6e^x',r'p=x+2+e^x',r'y=Ae^{-x}+Be^{-2x}+x+2+e^x')+'<p>The displayed PI is the sum of two independently verified responses. The complementary function is included once.</p>','second',a='1',b='3',c='2',forcing='2*x+7+6*exp(x)',solution='A*exp(-x)+B*exp(-2*x)+x+2+exp(x)'),
 E('P4','4 · Choose an initial slope to suppress growth',r'<p>For \(y^{\prime\prime}-y^{\prime}-2y=-2x\), keep y(0)=1 and choose y′(0)=v so that the growing exponential is absent.</p>',D(r'p=x-\frac12',r'y=Ae^{2x}+Be^{-x}+x-\frac12',r'A+B=\frac32,\qquad2A-B+1=v',r'A=\frac{2v+1}{6}',r'v=-\frac12,\qquad y=\frac32e^{-x}+x-\frac12')+'<p>The remaining solution still grows linearly. Its difference from x−1/2 tends to zero; y itself has no finite limit.</p>','second',a='1',b='-1',c='-2',forcing='-2*x',solution='3*exp(-x)/2+x-1/2',initial=[['0','1'],['0','-1/2',1]])])
L('oscillations','Oscillatory forcing, resonance and long-term behaviour','Distinguish a periodic response from its transient.',
 'Find harmonic responses and use supplied resonant trial forms with the correct initial data.',before('forcing'),
 r'''<h3>Use both sine and cosine in the trial</h3><p>For a sine, cosine or mixed input of frequency ω, try p=U sin(ωx)+V cos(ωx) when appropriate. The first derivative mixes the two functions, even if the input contains only one of them.</p>'''+D(r'L(p)=\bigl((c-a\omega^2)U-b\omega V\bigr)\sin\omega x',r'\quad+\bigl(b\omega U+(c-a\omega^2)V\bigr)\cos\omega x')+r'''<p>Match the sine and cosine coefficients separately. After finding the PI, include the CF and apply the conditions to the entire expression.</p><h3>Amplitude and phase need a convention</h3><p>For U sin(ωx)+V cos(ωx), the amplitude is sqrt(U²+V²). In R sin(ωx+φ), use R cos φ=U and R sin φ=V. The signs fix the quadrant; a tangent ratio alone does not. A cosine-based phase convention has different coefficient equations.</p><h3>When the trial overlaps a homogeneous mode</h3><p>A resonant input can make a usual exponential or harmonic trial disappear under L. In the written resonant tasks, the modified trial is supplied. Differentiate that given form and determine its coefficient by substitution. A repeated auxiliary root can require a squared polynomial factor rather than a single x.</p><h3>State the actual large-time conclusion</h3><p>If every CF mode decays, its difference from the particular response tends to zero. A non-constant periodic response still has no finite pointwise limit. If a growing CF mode has a non-zero coefficient, the periodic PI need not approximate the solution. Always inspect the actual constants and real parts.</p>''',
 ['Choose both harmonic terms or use the supplied resonant trial.','Differentiate the complete trial and match the input coefficients.','Add the complementary function and use both conditions.','Choose the phase quadrant from both sine and cosine coefficients.','Prove that the transient vanishes before claiming a long-term approximation.'],
 ['A pure cosine input can still need a sine term in the PI.','Keep the frequency factors in both derivatives.','A resonant trial has to be tested, not assigned a zero denominator.','The signs of two coefficients determine the phase quadrant.','An asymptotic periodic response does not imply a pointwise limit.'],[
 E('O1','1 · A periodic response after decay',r'<p>Solve \(y^{\prime\prime}+2y^{\prime}+5y=20\cos x\), y(0)=y′(0)=0, and describe the long-term response.</p>',D(r'p=U\sin x+V\cos x',r'4U-2V=0,\qquad2U+4V=20',r'U=2,\quad V=4',r'y=2\sin x+4\cos x',r'\quad-e^{-x}(4\cos2x+3\sin2x)')+r'<p>The difference from \(2\sin x+4\cos x=2\sqrt5\cos(x-\phi)\), with \(\tan\phi=1/2\) in the first quadrant, tends to zero. The solution has no finite pointwise limit.</p>','second',a='1',b='2',c='5',forcing='20*cos(x)',solution='2*sin(x)+4*cos(x)-exp(-x)*(4*cos(2*x)+3*sin(2*x))',initial=[['0','0'],['0','0',1]]),
 E('O2','2 · A PI that does not dominate',r'<p>For \(y^{\prime\prime}-2y^{\prime}+2y=5\sin x+5\cos x\), y(0)=4 and y′(0)=0, is the periodic PI a large-x approximation?</p>',D(r'p=-\sin x+3\cos x',r'y=e^x\cos x-\sin x+3\cos x')+'<p>No. The difference from p is eˣcos x, which does not tend to zero. Its values along full turns grow without bound, even though the difference vanishes at some other arguments.</p>','second',a='1',b='-2',c='2',forcing='5*sin(x)+5*cos(x)',solution='exp(x)*cos(x)-sin(x)+3*cos(x)',initial=[['0','4'],['0','0',1]]),
 E('O3','3 · Test a supplied resonant form',r'<p>For \(y^{\prime\prime}+y^{\prime}-2y=4e^x\), use the supplied trial \(p=Kxe^x\) and give the general solution.</p>',D(r'L(Kxe^x)=3Ke^x',r'K=\frac43',r'y=Ae^x+Be^{-2x}+\frac43xe^x')+'<p>The ordinary exponential trial duplicates a CF mode. The supplied extra x makes a non-zero input possible.</p>','second',a='1',b='1',c='-2',forcing='4*exp(x)',solution='A*exp(x)+B*exp(-2*x)+4*x*exp(x)/3'),
 E('O4','4 · A repeated resonant root',r'<p>For \(y^{\prime\prime}+6y^{\prime}+9y=8e^{-3x}\), use \(p=Kx^2e^{-3x}\). Find the solution with y(0)=2 and y′(0)=1.</p>',D(r'L(Kx^2e^{-3x})=2Ke^{-3x}',r'K=4,\qquad y=(A+Bx+4x^2)e^{-3x}',r'A=2,\qquad B-3A=1',r'y=(2+7x+4x^2)e^{-3x}')+'<p>The complete solution tends to zero. A fixed polynomial times a decaying exponential still decays.</p>','second',a='1',b='6',c='9',forcing='8*exp(-3*x)',solution='(2+7*x+4*x*x)*exp(-3*x)',initial=[['0','2'],['0','1',1]])])
L('substitutions','Substitutions, real branches and transformed conditions','Transform the derivatives and data before solving the simpler equation.',
 'Use the given dependent or independent variable substitution and recover the correct real solution.',before('oscillations')+'<p>Review the chain rule twice and <a href="/courses/maths4u-9231-fp2/topics/fp2_hyperbolic_inverse">inverse hyperbolic functions</a>. Some reduced first-order equations are separable.</p>',
 r'''<h3>Differentiate the given substitution explicitly</h3><p>For v=g(x)y, apply the product rule twice. For v=φ(y), apply the chain rule twice. These are different operations.</p>'''+D(r'v=gy:\quad v^{\prime}=g^{\prime}y+gy^{\prime}',r'v^{\prime\prime}=g^{\prime\prime}y+2g^{\prime}y^{\prime}+gy^{\prime\prime}',r'v=\phi(y):\quad v^{\prime}=\phi^{\prime}(y)y^{\prime}',r'v^{\prime\prime}=\phi^{\prime\prime}(y)(y^{\prime})^2+\phi^{\prime}(y)y^{\prime\prime}')+r'''<p>Substitute these expressions into the original relation. Simplify before dividing, and record any factor required to be non-zero. Initial derivatives change too; for v=gy use v′(x₀)=g′(x₀)y(x₀)+g(x₀)y′(x₀).</p><h3>A change of independent variable has two chain factors</h3><p>For x=eᵘ, write u=ln x and work on x&gt;0.</p>'''+D(r'xy_x=y_u,\qquad x^2y_{xx}=y_{uu}-y_u')+r'''<p>The negative first-derivative term comes from differentiating 1/x. The final answer must return to x, with the original initial data and domain.</p><h3>First-order substitutions and separation</h3><p>For y=xv, use y′=v+xv′. An affine combination z=ax+by has derivative z′=a+by′. After the given substitution, solve the resulting separable or linear equation. Dividing by a function of the new variable may exclude a constant solution; check it in the original equation.</p><h3>Recover the specified real branch</h3><p>A reciprocal needs a non-zero denominator. A positive square or fourth-root solution uses the positive root. A real cube root can be negative, but the recovered function must still have the differentiability required by the original equation. For the cubic substitution in Q69, a formal zero of v does not give permission to pass through y=0.</p><h3>Domain proof is part of the solution</h3><p>Check a radical stays non-negative, a logarithm has positive input, and any denominator stays non-zero on the proposed interval. A bound such as a positive quadratic minimum minus a decaying oscillation amplitude can establish global positivity.</p>''',
 ['Write the substitution and all required first and second derivatives.','Transform the initial values and derivative data at the correct point.','Solve the reduced equation while recording excluded cases.','Recover the original variable using the required real branch.','Check the original equation, conditions, differentiability and interval.'],
 ['A second chain derivative generally has two terms.','Initial derivative data also change under a substitution.','A reciprocal substitution can exclude the zero solution.','Choose the stated real branch rather than adding an unrelated sign.','A formal inverse formula must still satisfy the original domain and smoothness.'],[
 E('S1','1 · A product removes variable coefficients',r'<p>For x&gt;0, use v=xy to solve \(xy^{\prime\prime}+(2+3x)y^{\prime}+(3+2x)y=2x+3\).</p>',D(r'v^{\prime}=y+xy^{\prime},\qquad v^{\prime\prime}=2y^{\prime}+xy^{\prime\prime}',r'v^{\prime\prime}+3v^{\prime}+2v=2x+3',r'v=Ae^{-x}+Be^{-2x}+x',r'y=1+\frac{Ae^{-x}+Be^{-2x}}x')+'<p>The division by x is valid only on the stated interval. Substitution into the original variable-coefficient equation checks the recovery.</p>','product',multiplier='x',a='1',b='3',c='2',forcing='2*x+3',v='A*exp(-x)+B*exp(-2*x)+x'),
 E('S2','2 · Reciprocal substitution and an excluded solution',r'<p>Solve \(y^{\prime}+y=2y^2\), y(0)=1/3, using v=1/y.</p>',D(r'v^{\prime}=-\frac{y^{\prime}}{y^2}',r'v^{\prime}-v=-2,\qquad v(0)=3',r'v=2+e^x,\qquad y=\frac1{2+e^x}')+'<p>The denominator is positive for every real x. The original equation also has y=0 as a constant solution, but it does not satisfy this initial condition and is outside the reciprocal substitution.</p>','nonlinear_first',a='1',b='2',solution='1/(2+exp(x))',initial=[['0','1/3']]),
 E('S3','3 · Change the independent variable',r'<p>For x&gt;0, solve \(x^2y^{\prime\prime}+3xy^{\prime}+5y=10\ln x+4\), y(1)=y′(1)=1, using u=ln x.</p>',D(r'y_{uu}+2y_u+5y=10u+4',r'y(0)=1,\qquad y_u(0)=1',r'y=2u+e^{-u}(A\cos2u+B\sin2u)',r'A=1,\qquad B=0',r'y=2\ln x+\frac{\cos(2\ln x)}x')+'<p>The derivative relation xyₓ=yᵤ transforms the initial slope. Returning to x retains the restriction x&gt;0.</p>','euler',a='1',b='3',c='5',forcing='10*log(x)+4',solution='2*log(x)+cos(2*log(x))/x',initial=[['1','1'],['1','1',1]]),
 E('S4','4 · Recover only the positive square root',r'<p>A positive function satisfies \(yy^{\prime\prime}+(y^{\prime})^2+2yy^{\prime}+\frac52y^2=5e^{-x}\), y(0)=1 and y′(0)=−1/2. Use v=y².</p>',D(r'v^{\prime}=2yy^{\prime},\qquad v^{\prime\prime}=2(y^{\prime})^2+2yy^{\prime\prime}',r'v^{\prime\prime}+2v^{\prime}+5v=10e^{-x}',r'v=e^{-x}\left(\frac52-\frac32\cos2x\right)',r'y=\sqrt{\frac{(5-3\cos2x)e^{-x}}2}')+'<p>The bracket in v is at least 1, so v is positive for every real x. The positive square root satisfies the stated condition; the negative branch does not. Its bounded oscillating factor times e⁻ˣ tends to zero, so y also tends to zero.</p>','square',v='exp(-x)*(5-3*cos(2*x))/2',a='1',b='2',c='5',forcing='10*exp(-x)',initial=[['0','1'],['0','-1/2',1]])])
